-- "_trade_" -- the keeper this disabled duplicate mart points away from), so
-- wrapped the two bare casts in place. This model stays disabled (drop-list
-- duplicate, see above) -- fixed anyway since it's a landmine either way.

with source as (
    select * from {{ source('ripple_raw', 'FED_TRADE_CONSOLIDATED_SCREENING_LIST') }}
)

select
    ID as id,
    SOURCE as source,
    ENTITY_NUMBER as entity_number,
    TYPE as type,
    PROGRAMS as programs,
    NAME as name,
    TITLE as title,
    ADDRESSES as addresses,
    FEDERAL_REGISTER_NOTICE as federal_register_notice,
    {{ stg_date('START_DATE') }} as start_date,
    {{ stg_date('END_DATE') }} as end_date,
    STANDARD_ORDER as standard_order,
    LICENSE_REQUIREMENT as license_requirement,
    LICENSE_POLICY as license_policy,
    CALL_SIGN as call_sign,
    VESSEL_TYPE as vessel_type,
    GROSS_TONNAGE as gross_tonnage,
    GROSS_REGISTERED_TONNAGE as gross_registered_tonnage,
    VESSEL_FLAG as vessel_flag,
    VESSEL_OWNER as vessel_owner,
    REMARKS as remarks,
    SOURCE_LIST_URL as source_list_url,
    ALT_NAMES as alt_names,
    CITIZENSHIPS as citizenships,
    DATES_OF_BIRTH as dates_of_birth,
    NATIONALITIES as nationalities,
    PLACES_OF_BIRTH as places_of_birth,
